      '',
      'data: [DONE]',
      '',
    ].join('\n'))
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(new ReadableStream({
      start(controller) { controller.enqueue(encoded); controller.close() },
    }), { status: 200, headers: { 'Content-Type': 'text/event-stream' } })))
