            fi
          done < <(gh api "repos/${GITHUB_REPOSITORY}/releases/${release_id}/assets" --jq '.[] | [.id,.name] | @tsv')
          mapfile -t remote_assets < <(gh api "repos/${GITHUB_REPOSITORY}/releases/${release_id}/assets" --jq '.[].name')
          if [[ "${#remote_assets[@]}" -ne 1 || "${remote_assets[0]}" != "${EXPECTED_ASSET}" ]]; then
            printf '원격 Release 자산이 단일 파일 계약과 다릅니다: %s\n' "${remote_assets[*]}" >&2
